import { io } from "socket.io-client";
import { store } from "@/store/index.js";
// 创建socket实例（注意：生产环境应使用HTTPS）
export const socket = io("http://localhost:2525", {
  autoConnect: true,
  transports: ["websocket"],
});

export default {
  connectSocket,
  sendMessage,
  requestOnlineNumbers,
  socket,
  Request_UseName,
  Request_disconnet_infomation
};
